contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address baseToken,
        address nft,
        uint128 vBaseReserves,
        uint128 vNftReserves,
        uint56 changeFee,
        uint16 feeRate,
        bytes32 merkleRoot,
        bool useOracle,
        bool payRoy
    ) public {
        require(feeRate <= 5_000);

        c.initialize(
            baseToken,
            nft,
            vBaseReserves,
            vNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoy
        );

        bool secondReverted;
        bool ok = c.initialized();
        bool secondOk;
        try c.initialize(
            baseToken,
            nft,
            vBaseReserves,
            vNftReserves,
            changeFee,
            feeRate,
            merkleRoot,
            useOracle,
            payRoy
        ) { secondOk = true; } catch { secondOk = false; }
        secondReverted = !secondOk;

        assert(
            ok &&
            c.baseToken() == baseToken &&
            c.nft() == nft &&
            c.virtualBaseTokenReserves() == vBaseReserves &&
            c.virtualNftReserves() == vNftReserves &&
            c.changeFee() == changeFee &&
            c.feeRate() == feeRate &&
            c.merkleRoot() == merkleRoot &&
            c.useStolenNftOracle() == useOracle &&
            c.payRoyalties() == payRoy &&
            secondReverted
        );
    }
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 vBaseReserves,
        uint128 vNftReserves,
        uint256 outputAmount,
        uint16 feeRate
    ) public {
        require(feeRate <= 5_000);
        require(vNftReserves > 0 && outputAmount < vNftReserves);
        require(vBaseReserves <= 1e30 && outputAmount <= 1e24);

        c.initialize(
            address(0),
            address(0),
            vBaseReserves,
            vNftReserves,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.buyQuote(outputAmount);

        uint256 expectedInput = (outputAmount * vBaseReserves + (vNftReserves - outputAmount) - 1)
            / (vNftReserves - outputAmount);
        uint256 expectedFee = expectedInput * feeRate / 10_000;
        uint256 expectedProtocolFee = expectedInput * c.factory().call{value: 0}("") == bytes("") ? 0 : 0;
        expectedProtocolFee = expectedInput * Factory(c.factory()).protocolFeeRate() / 10_000;

        assert(
            netInputAmount == expectedInput + expectedFee + expectedProtocolFee &&
            feeAmount == expectedFee &&
            protocolFeeAmount == expectedProtocolFee &&
            protocolFeeAmount <= expectedInput * 5_000 / 10_000 + expectedInput / 10_000
        );
    }
    receive() external payable {}
}

