contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 vBaseReserves, uint128 vNftReserves, uint256 inputAmount, uint16 feeRate) public {
        require(vNftReserves > 0);
        require(uint256(vBaseReserves) <= 1e30);
        require(inputAmount <= 1e30);
        require(feeRate <= 5000);

        c.initialize(
            address(0),
            address(0),
            vBaseReserves,
            vNftReserves,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        (uint256 netOutput, uint256 feeAmount, uint256 protocolFeeAmount) = c.sellQuote(inputAmount);

        uint256 outputAmount = (inputAmount * uint256(vBaseReserves)) / (uint256(vNftReserves) + inputAmount);
        uint256 expectedFee = (outputAmount * feeRate) / 10000;
        uint256 expectedProtocolFee = (outputAmount * c.protocolFeeRate()) / 10000;

        assert(
            feeAmount == expectedFee &&
            protocolFeeAmount == expectedProtocolFee &&
            netOutput == outputAmount - expectedFee - expectedProtocolFee
        );
    }
    receive() external payable {}
}

