contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        address _baseToken,
        address _nft,
        uint128 _virtualBaseTokenReserves,
        uint128 _virtualNftReserves,
        uint56 _changeFee,
        uint16 _feeRate,
        bytes32 _merkleRoot,
        bool _useStolenNftOracle,
        bool _payRoyalties
    ) public {
        require(_feeRate <= 5000);

        // First initialize on a fresh pool must succeed and store parameters.
        c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        );

        bool initializedAfter = c.initialized();
        bool baseTokenOk = c.baseToken() == _baseToken;
        bool nftOk = c.nft() == _nft;
        bool vbrOk = c.virtualBaseTokenReserves() == _virtualBaseTokenReserves;
        bool vnrOk = c.virtualNftReserves() == _virtualNftReserves;
        bool changeFeeOk = c.changeFee() == _changeFee;
        bool feeRateOk = c.feeRate() == _feeRate;
        bool merkleRootOk = c.merkleRoot() == _merkleRoot;
        bool oracleOk = c.useStolenNftOracle() == _useStolenNftOracle;
        bool royaltiesOk = c.payRoyalties() == _payRoyalties;

        // A second initialize must always revert (AlreadyInitialized).
        bool reverted;
        try c.initialize(
            _baseToken,
            _nft,
            _virtualBaseTokenReserves,
            _virtualNftReserves,
            _changeFee,
            _feeRate,
            _merkleRoot,
            _useStolenNftOracle,
            _payRoyalties
        ) {
            reverted = false;
        } catch {
            reverted = true;
        }

        assert(
            initializedAfter &&
            baseTokenOk &&
            nftOk &&
            vbrOk &&
            vnrOk &&
            changeFeeOk &&
            feeRateOk &&
            merkleRootOk &&
            oracleOk &&
            royaltiesOk &&
            reverted
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 vbr,
        uint128 vnr,
        uint16 feeRate,
        uint256 outputAmount
    ) public {
        // Preconditions on parameters only.
        require(feeRate <= 5000);
        require(vbr <= 1e18);
        require(vnr > 0 && vnr <= 2e18);
        require(outputAmount <= 1e18 && outputAmount < vnr);

        // Set up pool state (top-level state-changing call).
        c.initialize(
            address(0),
            address(1),
            vbr,
            vnr,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        // Independently compute expected gross input: ceil(outputAmount*vbr/(vnr-outputAmount)).
        uint256 denom = vnr - outputAmount; // >= 1
        uint256 expectedGrossInput = (outputAmount * vbr + denom - 1) / denom;
        uint256 expectedFee = expectedGrossInput * feeRate / 10000;

        (uint256 netInputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.buyQuote(outputAmount);

        // Rule: net = gross + fee + protocol, and fee = gross * feeRate / 10000.
        assert(
            netInputAmount == expectedGrossInput + feeAmount + protocolFeeAmount &&
            feeAmount == expectedFee
        );
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(
        uint128 vbr,
        uint128 vnr,
        uint16 feeRate,
        uint256 inputAmount
    ) public {
        // Preconditions on parameters only.
        require(feeRate <= 5000);
        require(vbr <= 1e18);
        require(vnr > 0 && vnr <= 2e18);
        require(inputAmount <= 1e18);

        // Set up pool state (top-level state-changing call).
        c.initialize(
            address(0),
            address(1),
            vbr,
            vnr,
            0,
            feeRate,
            bytes32(0),
            false,
            false
        );

        // Independently compute expected values: factory protocolFeeRate defaults to 0.
        uint256 expectedOutput = inputAmount * vbr / (vnr + inputAmount);
        uint256 expectedFee = expectedOutput * feeRate / 10000;

        (uint256 netOutputAmount, uint256 feeAmount, uint256 protocolFeeAmount) =
            c.sellQuote(inputAmount);

        // Rule: net = output - fee - protocol, fee = output * feeRate / 10000, protocol = 0.
        assert(
            netOutputAmount == expectedOutput - expectedFee &&
            feeAmount == expectedFee &&
            protocolFeeAmount == 0
        );
    }

    receive() external payable {}
}
